// "まとめ": every real Unit's words pooled together (de-duplicated by
// English form — a word repeated across Units, e.g. "improve", keeps the
// version from whichever Unit lists it first) for PLAY / Final Boss review
// across everything at once.
function dedupeWords(wordArrays) {
  const seen = new Set();
  const result = [];
  wordArrays.forEach(arr => {
    arr.forEach(w => {
      if (!seen.has(w.en)) { seen.add(w.en); result.push(w); }
    });
  });
  return result;
}
const SUMMARY_WORDS = dedupeWords([
  UNIT1_WORDS, UNIT2_WORDS, UNIT3_WORDS, LR1_WORDS, UNIT4_WORDS,
  UNIT5_WORDS, UNIT6_WORDS, LR2_WORDS, LR3_WORDS, EXAM_WORDS,
]);

